expect(client).toMatch(/next=\{nextItem \? nameOf\(nextItem\) : undefined\}/);
expect(client).toMatch(/const at = Math\.min\(index, items\.length - 1\);/);
expect(client).toMatch(/if \(items\.length === 0 \|\| !current\)/);

/**
 * Ledger: 이름 · 값 목록을 담는 장부(dl). 담긴 자리의 폭이 420 아래면 이름 위 · 값 아래로 쌓는다.
 * 겉 상자(Bx · 테두리 div)로 감싸지 않는다: 줄 사이 선이 이미 묶음을 보여 준다.
 */
export function Ledger({ children, ariaLabel, className }: { children: ReactNode; ariaLabel?: string; className?: string }) {
  return (
    <dl className={className ? `qa-ledger ${className}` : 'qa-ledger'} aria-label={ariaLabel}>
      {children}
    </dl>
  );
}

/** 한 칸에서 상세 머리를 올릴 기준: 바깥 상자의 scroll-margin-top(폰 상단 바 높이)보다 위로 갔으면 올린다 */
function listDetailAboveFold(host: HTMLElement): boolean {
  return host.getBoundingClientRect().top < (parseFloat(getComputedStyle(host).scrollMarginTop) || 0);
}

/** 목록 + 상세에서 한 칸만 보일 때(담긴 자리 700 아래)인가: 상세 칸이 숨었거나 목록 칸이 숨었으면 한 칸이다 */
function listDetailSingle(host: HTMLElement | null): boolean {
  const list = host?.querySelector<HTMLElement>('.qa-ld-list');
  const detail = host?.querySelector<HTMLElement>('.qa-ld-detail');
  if (!list || !detail) return false;
  return getComputedStyle(list).display === 'none' || getComputedStyle(detail).display === 'none';
}

/**
 * ListDetail: 왼쪽 목록 · 오른쪽 상세(2026-10-15 오너 결정 · 용어집 시안 C).
 *
 * 화면 폭이 아니라 «담긴 자리의 폭» 을 본다(@container). 용어집은 전용 화면과 AI 도우미의 좁은 탭이
 * 같은 부품이라, 같은 화면 폭에서도 자리마다 한 칸 · 두 칸이 갈린다.
 *   · 두 칸(700 이상): 목록과 상세가 각자 굴러간다. 선택은 면 색 + 굵은 제목(왼쪽 강조선 금지).
 *   · 한 칸: `view` 가 보일 칸을 고른다. 상세 위에 «← 목록» 글귀가 선다.
 * 목록에서 ↑ ↓ (Home · End)로 줄을 옮긴다. 두 칸이면 옮기는 즉시 상세가 바뀌고, 한 칸이면 초점만 옮긴다.
 * 선택 · 보기 상태는 쓰는 쪽이 쥔다(고르면 view 를 'detail' 로, 뒤로는 'list' 로).
 */
export function ListDetail({
  list,
  detail,
  view,
  onBack,
  detailKey,
  listLabel,
  detailLabel,
  backLabel = '목록',
  height,
}: {
  list: ReactNode;
  detail: ReactNode;
  /** 한 칸일 때 보일 칸 */
  view: 'list' | 'detail';
  /** «← 목록» 을 눌렀을 때(한 칸에서만 보인다) */
  onBack: () => void;
  /** 상세가 바뀌는 열쇠(고른 항목 id). 바뀌면 상세가 맨 위에서 살짝 떠오른다 */
  detailKey?: string | number;
  listLabel: string;
  detailLabel: string;
  backLabel?: string;
  /** 두 칸일 때 높이(CSS 값). 기본은 화면 높이에 맞춘 값 */
  height?: string;
}) {
  const hostRef = useRef<HTMLDivElement>(null);
  const detailRef = useRef<HTMLElement>(null);
  const firstView = useRef(true);

  // 상세가 바뀌면 상세 칸은 맨 위부터. 두 칸이면 상세 칸이 스스로 굴러가고,
  // 한 칸이면 바깥(main · 서랍)이 굴러가므로 상세 머리가 화면 위로 지나갔을 때만 되돌린다(같은 분야 · 다음 건으로 건너갈 때)
  useEffect(() => {
    if (detailRef.current) detailRef.current.scrollTop = 0;
    const host = hostRef.current;
    if (host && view === 'detail' && listDetailSingle(host) && listDetailAboveFold(host)) host.scrollIntoView({ block: 'start' });
  }, [detailKey]);

  // 한 칸에서 칸을 바꾸면: 상세로 가면 상세 머리로 초점 · 화면을, 목록으로 오면 고른 줄로 되돌린다
  useEffect(() => {
    if (firstView.current) {
      firstView.current = false;
      return;
    }
    const host = hostRef.current;
    if (!host || !listDetailSingle(host)) return;
    if (view === 'detail') {
      // 목록 아래쪽에서 골랐으면 상세 머리(← 목록)까지 올린다
      if (listDetailAboveFold(host)) host.scrollIntoView({ block: 'start' });
      detailRef.current?.focus({ preventScroll: true });
    } else {
      const row = host.querySelector<HTMLElement>('.qa-ld-row[aria-current="true"]');
      row?.scrollIntoView({ block: 'center' });
      row?.focus({ preventScroll: true });
    }
  }, [view]);

  const onListKey = (e: KeyboardEvent<HTMLElement>) => {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp' && e.key !== 'Home' && e.key !== 'End') return;
    const rows = Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>('[data-ld-row]'));
    const at = rows.indexOf(document.activeElement as HTMLButtonElement);
    if (at < 0) return;
    e.preventDefault();
    const to = e.key === 'Home' ? 0 : e.key === 'End' ? rows.length - 1 : Math.min(rows.length - 1, Math.max(0, at + (e.key === 'ArrowDown' ? 1 : -1)));
    const row = rows[to];
    row.focus();
    if (!listDetailSingle(hostRef.current)) row.click();
  };

  return (
    <div className="qa-ld-host" ref={hostRef}>
      <div className="qa-ld" data-view={view} style={height ? ({ ['--qa-ld-height' as string]: height } as CSSProperties) : undefined}>
        <section className="qa-ld-list" aria-label={listLabel} onKeyDown={onListKey}>
          {list}
        </section>
        <section className="qa-ld-detail" aria-label={detailLabel} ref={detailRef} tabIndex={-1}>
          <button type="button" className="qa-ld-back" onClick={onBack}>
            ← {backLabel}
          </button>
          <div key={detailKey} className="qa-ld-in">
            {detail}
          </div>
        </section>
      </div>
    </div>
  );
}

/** 목록 칸의 묶음 머리(분류 이름 + 건수). 두 칸일 때 목록 위에 붙어 따라온다 */
export function ListDetailGroup({ title, count }: { title: ReactNode; count?: number }) {
  return (
    <div className="qa-ld-gh">
      <span>{title}</span>
      {count != null && <span className="qa-ld-n">{count}</span>}
    </div>
  );
}

/**
 * 목록 칸의 한 줄. 고르면 면 색이 깔리고 제목이 굵어진다(aria-current).
 * 두 칸에서 이전 · 다음으로 고른 줄이 목록 밖으로 나가면 목록 칸만 굴려 보이게 한다(바깥 화면은 굴리지 않는다).
 */
export function ListDetailRow({
  selected,
  onSelect,
  title,
  sub,
  code,
  label,
}: {
  selected: boolean;
  onSelect: () => void;
  title: ReactNode;
  sub?: ReactNode;
  /** 제목이 약어 · 번호(DHF · ISO 13485 · CAPA-0012)면 고정폭 글꼴 */
  code?: boolean;
  /** 낭독기 이름(보이는 제목이 앞에 와야 한다) */
  label?: string;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const row = ref.current;
    const box = row?.closest<HTMLElement>('.qa-ld-list');
    if (!selected || !row || !box || box.scrollHeight <= box.clientHeight) return;
    if (getComputedStyle(box).overflowY === 'visible') return;
    const r = row.getBoundingClientRect();
    const b = box.getBoundingClientRect();
    if (r.top < b.top + 40) box.scrollTop -= b.top + 40 - r.top;
    else if (r.bottom > b.bottom) box.scrollTop += r.bottom - b.bottom;
  }, [selected]);
  return (
    <button
      ref={ref}
      type="button"
      className="qa-ld-row"
      data-ld-row=""
      aria-current={selected ? 'true' : undefined}
      aria-label={label}
      onClick={onSelect}
    >
      <span className={code ? 'qa-ld-row-title is-code' : 'qa-ld-row-title'}>{title}</span>
      {sub != null && sub !== '' && <span className="qa-ld-row-sub">{sub}</span>}
    </button>
  );
}

/**
 * 상세 칸의 머리: 위치 줄(번호 · 분류 · 몇 번째) → 큰 제목 → 곁말 → 한 줄 요약.
 * 제목이 약어 · 번호면 `code` 로 고정폭 금색 큰 글자(용어집 시안 C 의 얼굴).
 */
export function ListDetailHead({
  kicker,
  position,
  title,
  code,
  aside,
  lede,
}: {
  kicker?: ReactNode;
  /** 오른쪽 끝의 «3 / 140» */
  position?: string;
  title: ReactNode;
  code?: boolean;
  aside?: ReactNode;
  lede?: ReactNode;
}) {
  return (
    <header>
      {(kicker != null || position) && (
        <div className="qa-ld-kicker">
          {kicker}
          {position && <span className="is-end">{position}</span>}
        </div>
      )}
      <h2 className={code ? 'qa-ld-title is-code' : 'qa-ld-title'}>{title}</h2>
      {aside != null && aside !== '' && <p className="qa-ld-aside">{aside}</p>}
      {lede != null && lede !== '' && <p className="qa-ld-lede">{lede}</p>}
    </header>
  );
}

/** 상세 칸 바닥의 이전 · 다음 글귀. 끝이면 그쪽 자리를 비운다 */
export function ListDetailNav({
  prev,
  next,
  onPrev,
  onNext,
  disabled,
}: {
  prev?: string;
  next?: string;
  onPrev: () => void;
  onNext: () => void;
  /** 보내는 중(결재 서명 등)에는 건너가지 못하게 */
  disabled?: boolean;
}) {
  return (
    <nav className="qa-ld-nav" aria-label="이전 · 다음">
      {prev ? <TextAction onClick={onPrev} disabled={disabled} label={`이전: ${prev}`}>← {prev}</TextAction> : <span />}
      {next ? <TextAction onClick={onNext} disabled={disabled} label={`다음: ${next}`}>{next} →</TextAction> : <span />}
    </nav>
  );
}

/* =============================================================================
   장부형 패턴 층 (2026-10-15 오너 결정 · 용어집 시안 비교판에서 A + C)
   A 장부 두 칸(Ledger · DetailRow): 이름 칸 + 값 칸, 상자 없이 줄 사이 가는 선. 좁으면 위아래로 쌓는다.
   C 목록 + 상세(ListDetail): 왼쪽 목록 · 오른쪽 상세. 담긴 자리의 폭이 700 아래면 한 칸씩(목록 → 상세 → 목록).
     화면 폭이 아니라 «담긴 자리» 를 본다: 용어집은 전용 화면과 AI 도우미의 좁은 탭이 같은 부품이다.
   선택은 면 색 + 굵은 제목(왼쪽 강조선 금지 · no-side-accent). 한글 자간은 0.
   ============================================================================= */
.qa-ledger {
  container-type: inline-size;
  width: 100%;
  min-width: 0;
  margin: 0;
}
.qa-ledger-row {
  display: grid;
  grid-template-columns: minmax(6.5rem, var(--qa-ledger-label, 12rem)) minmax(0, 1fr);
  column-gap: 24px;
  row-gap: 2px;
  align-items: baseline;
  margin: 0;
  padding: 11px 0 12px;
  border-bottom: 1px solid var(--qa-border);
}
.qa-ledger > .qa-ledger-row:last-child {
  border-bottom: none;
}
.qa-ledger-label {
  margin: 0;
  color: var(--qa-muted);
  font-size: 13.5px;
  line-height: var(--qa-lh-normal);
  word-break: keep-all;
  overflow-wrap: break-word;
}
.qa-ledger-value {
  margin: 0;
  min-width: 0;
  color: var(--qa-text);
  font-size: 14px;
  line-height: var(--qa-lh-relaxed);
  overflow-wrap: anywhere;
}
@container (max-width: 420px) {
  .qa-ledger-row {
    grid-template-columns: minmax(0, 1fr);
    padding: 10px 0 11px;
  }
}

.qa-ld-host {
  container-type: inline-size;
  width: 100%;
  min-width: 0;
  /* 한 칸에서 상세로 건너가 머리로 올릴 때 폰 상단 바(68)에 가리지 않게 */
  scroll-margin-top: 80px;
}
.qa-ld {
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(0, 1fr);
  height: var(--qa-ld-height, min(760px, calc(100dvh - 220px)));
  min-height: 420px;
  border-top: 1px solid var(--qa-borderHi);
}
.qa-ld-list {
  min-width: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-right: 1px solid var(--qa-borderHi);
  padding-bottom: 24px;
}
.qa-ld-gh {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px 6px 0;
  background: var(--qa-bg);
  border-bottom: 1px solid var(--qa-border);
  color: var(--qa-muted);
  font-size: 12.5px;
  font-weight: 600;
}
.qa-ld-n {
  font-family: var(--qd-font-family-mono);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}
.qa-ld-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
  width: 100%;
  min-height: 52px;
  margin: 0;
  padding: 10px 16px 11px 10px;
  border: none;
  border-bottom: 1px solid var(--qa-border);
  border-radius: 0;
  background: transparent;
  color: var(--qa-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.12s ease;
}
.qa-ld-row:hover {
  background: var(--qa-surface);
}
.qa-ld-row[aria-current='true'] {
  background: var(--qa-surface2);
}
.qa-ld-row:focus-visible {
  outline: 2px solid var(--qa-champagne);
  outline-offset: -2px;
}
.qa-ld-row-title {
  font-size: 14px;
  font-weight: 600;
  line-height: var(--qa-lh-snug);
  overflow-wrap: anywhere;
}
.qa-ld-row[aria-current='true'] .qa-ld-row-title {
  font-weight: 800;
}
.qa-ld-row-title.is-code {
  font-family: var(--qd-font-family-mono);
  font-size: 13.5px;
}
.qa-ld-row-sub {
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--qa-subtle);
  font-size: 13px;
  line-height: var(--qa-lh-normal);
}
.qa-ld-row[aria-current='true'] .qa-ld-row-sub {
  color: var(--qa-text);
}
.qa-ld-detail {
  min-width: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 32px 8px 40px 44px;
}
.qa-ld-in {
  max-width: 680px;
  animation: qa-ld-in 0.24s ease both;
}
@keyframes qa-ld-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}
.qa-ld-back {
  display: none;
  align-items: center;
  gap: 4px;
  min-height: 44px;
  margin: 0 0 4px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--qa-subtle);
  font: inherit;
  font-size: 13.5px;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: var(--qa-border);
  text-underline-offset: 3px;
}
.qa-ld-back:hover {
  color: var(--qa-text);
  text-decoration-color: var(--qa-champagne);
}
/* 상세 머리: 위치 줄(번호 · 분류 · 몇 번째) → 큰 제목 → 한 줄 요약 → 본문 */
.qa-ld-kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 10px;
  margin: 0 0 12px;
  color: var(--qa-muted);
  font-size: 12.5px;
}
.qa-ld-kicker .is-code {
  font-family: var(--qd-font-family-mono);
  color: var(--qa-champagne);
}
.qa-ld-kicker .is-end {
  margin-left: auto;
  font-family: var(--qd-font-family-mono);
  font-variant-numeric: tabular-nums;
}
.qa-ld-title {
  margin: 0;
  color: var(--qa-text);
  font-size: 24px;
  font-weight: 700;
  line-height: var(--qa-lh-heading);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.qa-ld-title.is-code {
  font-family: var(--qd-font-family-mono);
  font-size: 32px;
  font-weight: 600;
  line-height: var(--qa-lh-tight);
  color: var(--qa-champagne);
}
.qa-ld-aside {
  margin: 8px 0 0;
  color: var(--qa-muted);
  font-size: 14px;
}
.qa-ld-lede {
  margin: 20px 0 0;
  color: var(--qa-text);
  font-size: 18px;
  font-weight: 700;
  line-height: var(--qa-lh-snug);
}
.qa-ld-body {
  margin: 10px 0 0;
  max-width: 62ch;
  color: var(--qa-subtle);
  font-size: 15px;
  line-height: var(--qa-lh-loose);
}
.qa-ld-facts {
  margin-top: 26px;
  border-top: 1px solid var(--qa-borderHi);
}
.qa-ld-nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px 16px;
  margin-top: 24px;
}
.qa-ld-empty {
  padding: 40px 0;
  color: var(--qa-muted);
  font-size: 14px;
}
@container (max-width: 699px) {
  .qa-ld {
    display: block;
    height: auto;
    min-height: 0;
  }
  .qa-ld-list {
    overflow: visible;
    border-right: none;
    padding-bottom: 0;
  }
  /* 한 칸일 때 목록은 바깥(main · 서랍)이 굴린다. 거기서 top 0 고정은 폰 상단 바 밑으로 숨으므로 풀어 둔다(sticky-inset) */
  .qa-ld-gh {
    position: static;
  }
  .qa-ld[data-view='detail'] .qa-ld-list,
  .qa-ld[data-view='list'] .qa-ld-detail {
    display: none;
  }
  .qa-ld-detail {
    overflow: visible;
    padding: 12px 0 32px;
  }
  /* 상세가 짧아도 머리(← 목록)를 상단 바 아래로 올릴 만큼의 높이(짧으면 바깥 스크롤이 끝에 걸려 머리가 바에 반쯤 가린다) */
  .qa-ld[data-view='detail'] .qa-ld-detail {
    min-height: 70dvh;
  }
  .qa-ld-back {
    display: inline-flex;
  }
  .qa-ld-row {
    padding-left: 0;
  }
  .qa-ld-row[aria-current='true'] {
    padding-left: 10px;
  }
  .qa-ld-title.is-code {
    font-size: 28px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .qa-ld-in { animation: none; }
  .qa-ld-row { transition: none; }
}

/* =============================================================================
   장부형 패턴 층 (2026-10-15 오너 결정 · 용어집 시안 비교판에서 A + C)
